-- Coldridge Valley / Frostmane Hold: start each patrol path at its own spawn point.
--
-- Eleven paths added by this branch begin at whichever node the sniff happened to
-- see first, which is an accident of when the player walked up. The core sends a
-- freshly spawned NPC to point 1 before it patrols anything, so Rockjaw Goon
-- 167220 was walking 114 yd across the valley on every respawn, and Coldridge
-- Mountaineer 167027 was crossing 153 yd of it.
--
-- waypoint_data is cyclic -- WaypointMovementGenerator advances
-- (i_currentNode + 1) % size -- so rotating the list changes nothing about the
-- route walked, only where it is entered. Each row keeps its own delay and
-- move_type; only `point` is renumbered.
--
-- Every path in the rest of the DB already follows this convention: of the
-- pre-existing paths on map 0, all of them have point 1 sitting on the spawn
-- point exactly. These eleven were the exception.
--
--   guid    entry  path       point 1 was    now
--   166972  853    1669720    20.3 yd        0.00
--   166975  853    1669750    30.1 yd        0.00
--   166999  37087  1669990     5.1 yd        0.00
--   167012  37218  1670120     9.7 yd        0.00
--   167017  37218  1670170    35.8 yd        0.00
--   167026  853    1670260    37.4 yd        6.21
--   167027  853    1670270   153.5 yd        7.33
--   167038  37218  1670380    17.7 yd        0.00
--   167209  37507  1672090    17.1 yd        0.00
--   167220  37073  1672200   114.6 yd        0.00
--   167308  37112  1673080    10.6 yd        0.00
--
-- 167026 and 167027 keep a residual because their spawn point is not one of
-- their waypoints -- they are the two Mountaineers whose retail pairing was
-- inexact at 6.2 and 7.3 yd. Point 1 is now the nearest node to each, which is
-- as close as rotation can get; closing the gap entirely would mean moving the
-- spawn onto the path, which is a separate decision about where the NPC stands.
--
-- 167020 (Sten Stoutarm) already started on its spawn point and is not here.

-- guid 166972 (entry 853), path 1669720: 42 points rotated by 7 --
--   point 1 was 20.3 yd from the spawn point, is now 0.00 yd (old point 8 becomes point 1)
DELETE FROM `waypoint_data` WHERE `id`=1669720;

-- guid 166975 (entry 853), path 1669750: 15 points rotated by 5 --
--   point 1 was 30.1 yd from the spawn point, is now 0.00 yd (old point 6 becomes point 1)
DELETE FROM `waypoint_data` WHERE `id`=1669750;

-- guid 166999 (entry 37087), path 1669990: 12 points rotated by 11 --
--   point 1 was 5.1 yd from the spawn point, is now 0.00 yd (old point 12 becomes point 1)
DELETE FROM `waypoint_data` WHERE `id`=1669990;

-- guid 167012 (entry 37218), path 1670120: 25 points rotated by 13 --
--   point 1 was 9.7 yd from the spawn point, is now 0.00 yd (old point 14 becomes point 1)
DELETE FROM `waypoint_data` WHERE `id`=1670120;

-- guid 167017 (entry 37218), path 1670170: 9 points rotated by 5 --
--   point 1 was 35.8 yd from the spawn point, is now 0.00 yd (old point 6 becomes point 1)
DELETE FROM `waypoint_data` WHERE `id`=1670170;

-- guid 167026 (entry 853), path 1670260: 11 points rotated by 5 --
--   point 1 was 37.4 yd from the spawn point, is now 6.21 yd (old point 6 becomes point 1)
DELETE FROM `waypoint_data` WHERE `id`=1670260;

